// Opt-in deferred startup. Ordinary Scene3D routes do not fetch this chunk.
// @ts-check
  /**
   * @param {HTMLElement} mount
   * @param {() => boolean} isCurrent
   * @returns {Promise<boolean>}
   */
  function sceneWaitForIdleVisible(
    // @ts-ignore TS7006 -- keep this helper parseable by the raw-JS runtime harness.
    mount, isCurrent
  ) {
    return new Promise(function(resolve) {
      let idle = false;
      let painted = false;
      let finished = false;
      let intersectionObserver = new Array().pop();
      let mutationObserver = new Array().pop();
      let idleTimer = new Array().pop();
      const cleanup = new Array();
      const connection = Reflect.get(window.navigator, "connection");

      /** @param {boolean} eligible */
      function finish(
        // @ts-ignore TS7006 -- keep this helper parseable by the raw-JS runtime harness.
        eligible
      ) {
        if (finished) return;
        finished = true;
        if (intersectionObserver) intersectionObserver.disconnect();
        if (mutationObserver) mutationObserver.disconnect();
        if (idleTimer != null) clearTimeout(idleTimer);
        cleanup.forEach(function(remove) { remove(); });
        resolve(Boolean(eligible));
      }

      /**
       * @param {EventTarget | null} target
       * @param {string} type
       * @param {EventListener} callback
       * @param {AddEventListenerOptions | boolean | undefined} [options]
       */
      function listener(
        // @ts-ignore TS7006 -- keep this helper parseable by the raw-JS runtime harness.
        target, type, callback, options = undefined
      ) {
        if (!target || typeof target.addEventListener !== "function") return;
        target.addEventListener(type, callback, options);
        cleanup.push(function() { target.removeEventListener(type, callback, options); });
      }

      /** @returns {boolean} */
      function visibleByRect() {
        if (!mount || typeof mount.getBoundingClientRect !== "function") return false;
        const rect = mount.getBoundingClientRect();
        const width = Number(window.innerWidth) || 0;
        const height = Number(window.innerHeight) || 0;
        return rect.width > 0 && rect.height > 0 && rect.right > 0 && rect.bottom > 0
          && rect.left < width && rect.top < height;
      }

      /** @returns {boolean} */
      function reducedMotion() {
        return typeof window.matchMedia === "function"
          && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      }

      /** @returns {boolean} */
      function saveData() {
        return Boolean(connection && connection.saveData);
      }

      function check() {
        if (finished) return;
        if (!isCurrent()) {
          finish(false);
          return;
        }
        if (mount.id && document.getElementById(mount.id) !== mount) {
          finish(false);
          return;
        }
        if (reducedMotion() || saveData()) {
          finish(false);
          return;
        }
        if (!idle || !painted || document.visibilityState !== "visible") return;
        if (typeof IntersectionObserver !== "undefined") {
          // IntersectionObserver owns visibility when present. The rect check
          // also covers the first turn before its first observer callback.
          if (!visibleByRect() && !intersectionObserver.__gosxIntersecting) return;
        } else if (!visibleByRect()) {
          return;
        }
        finish(true);
      }

      if (typeof IntersectionObserver !== "undefined") {
        intersectionObserver = new IntersectionObserver(function(entries) {
          for (let i = 0; i < entries.length; i += 1) {
            if (entries[i].target === mount) {
              intersectionObserver.__gosxIntersecting = Boolean(entries[i].isIntersecting);
              break;
            }
          }
          check();
        }, { threshold: 0.01 });
        intersectionObserver.__gosxIntersecting = false;
        intersectionObserver.observe(mount);
      }
      listener(document, "visibilitychange", check);
      listener(window, "scroll", check, { passive: true });
      listener(window, "resize", check, { passive: true });
      listener(window, "pagehide", function() { finish(false); });
      if (typeof window.matchMedia === "function") {
        const motionQuery = window.matchMedia("(prefers-reduced-motion: reduce)");
        if (typeof motionQuery.addEventListener === "function") {
          listener(motionQuery, "change", check);
        } else if (typeof motionQuery.addListener === "function") {
          motionQuery.addListener(check);
          cleanup.push(function() { motionQuery.removeListener(check); });
        }
      }
      listener(connection, "change", check);
      if (typeof MutationObserver !== "undefined" && document.documentElement) {
        mutationObserver = new MutationObserver(check);
        mutationObserver.observe(document.documentElement, { childList: true, subtree: true });
      }
      if (typeof window.requestIdleCallback === "function") {
        /** @param {IdleDeadline} deadline */
        const markIdle = function(
          // @ts-ignore TS7006 -- keep this helper parseable by the raw-JS runtime harness.
          deadline
        ) {
          // A timeout means the browser forced this callback while busy. Keep
          // the poster until it grants a real idle slice.
          if (deadline && deadline.didTimeout) {
            window.requestIdleCallback(markIdle, { timeout: 2000 });
            return;
          }
          idle = true;
          check();
        };
        window.requestIdleCallback(markIdle, { timeout: 2000 });
      } else {
        idleTimer = setTimeout(function() { idle = true; check(); }, 1000);
      }
      const markPainted = function() {
        painted = true;
        check();
      };
      if (typeof window.requestAnimationFrame === "function") {
        window.requestAnimationFrame(function() {
          window.requestAnimationFrame(markPainted);
        });
      } else {
        setTimeout(markPainted, 0);
      }
      check();
    });
  }

  /**
   * @param {Record<string, any>} props
   * @returns {Promise<{ softwareWebGL: boolean; hardware: boolean }>}
   */
  async function sceneProbeStartBackend(
    // @ts-ignore TS7006 -- keep this helper parseable by the raw-JS runtime harness.
    props
  ) {
    const nav = window.navigator || {};
    const gpu = Reflect.get(nav, "gpu");
    const forcedWebGL = Boolean(props && (props.forceWebGL || props.requireWebGL))
      || window.__gosx_scene3d_force_webgl === true
      || (typeof window.__gosx_scene3d_force_webgl_requested === "function" && window.__gosx_scene3d_force_webgl_requested());
    let webgl = { available: false, software: false };
    if (typeof sceneProbeWebGLRenderer === "function") {
      try { webgl = sceneProbeWebGLRenderer() || webgl; } catch (_error) { webgl = { available: false, software: false }; }
    }
    const webglHardware = Boolean(webgl.available && !webgl.software);
    let webgpuHardware = false;
    // A hardware WebGL context is enough to establish that this device has an
    // accelerated backend. Avoid a serial requestAdapter() here: on a cold
    // browser it can take seconds, and the selected WebGPU backend performs
    // its own readiness probe immediately after this startup policy returns.
    // Keep the WebGPU check for software or unavailable WebGL so hybrid
    // devices with hardware WebGPU remain eligible.
    if (!forcedWebGL && !webglHardware && gpu && typeof gpu.requestAdapter === "function") {
      try {
        const adapter = await gpu.requestAdapter({ powerPreference: "high-performance" });
        if (adapter) {
          let info = adapter.info || {};
          if ((!info.vendor && !info.device && !info.description) && typeof adapter.requestAdapterInfo === "function") {
            try { info = await adapter.requestAdapterInfo(); } catch (_error) { info = {}; }
          }
          const identity = [info.vendor, info.architecture, info.device, info.description].join(" ").toLowerCase();
          const software = /swiftshader|llvmpipe|softpipe|lavapipe|software|basic render/.test(identity);
          webgpuHardware = !software;
        }
      } catch (_error) {
        webgpuHardware = false;
      }
    }
    return {
      softwareWebGL: Boolean(webgl.available && webgl.software),
      hardware: forcedWebGL ? webglHardware : (webgpuHardware || webglHardware),
    };
  }

  async function sceneRunStartPolicy(
    // @ts-ignore TS7006 -- keep this helper parseable by the raw-JS runtime harness.
    mount, props, ctx
  ) {
    const policy = String(props.startPolicy || "").trim().toLowerCase();
    if (policy !== "idle-visible-hardware") return true;
    mount.setAttribute("data-gosx-scene3d-start-policy", policy);
    const current = function() { return !ctx.isCurrent || ctx.isCurrent(); };
    if (!(await sceneWaitForIdleVisible(mount, current))) {
      if (current()) setAttrValue(mount, "data-gosx-scene3d-start-state", "poster");
      return false;
    }
    const backend = await sceneProbeStartBackend(props);
    setAttrValue(mount, "data-gosx-scene3d-software-webgl", backend.softwareWebGL ? "true" : "false");
    if (!backend.hardware) {
      setAttrValue(mount, "data-gosx-scene3d-start-state", "poster");
      return false;
    }
    setAttrValue(mount, "data-gosx-scene3d-start-state", "starting");
    return true;
  }
